using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins("http://localhost:5173","http://localhost:5174").AllowAnyHeader().AllowAnyMethod()));
builder.Services.AddDbContext<BookingDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Saloon")??throw new InvalidOperationException("Set ConnectionStrings__Saloon.")));
var app=builder.Build();app.UseCors();app.MapGet("/health",()=>Results.Ok(new{service="appointments",status="healthy"}));
app.MapGet("/api/appointments",async(DateOnly? date,BookingDb db)=>Results.Ok(await db.Appointments.Where(a=>date==null||a.StartAt.Date==date.Value.ToDateTime(TimeOnly.MinValue).Date).OrderBy(a=>a.StartAt).ToListAsync()));
app.MapGet("/api/appointments/slots",async(DateOnly date,int serviceId,BookingDb db)=>{var s=await db.Services.FindAsync(serviceId);if(s is null||!s.IsActive)return Results.NotFound();var start=date.ToDateTime(new TimeOnly(9,0));var end=date.ToDateTime(new TimeOnly(18,0));var now=DateTime.Now;var busy=await db.Appointments.Where(a=>a.StartAt.Date==start.Date&&a.Status!="Cancelled").Select(a=>new{a.StartAt,a.DurationMinutes}).ToListAsync();var slots=new List<string>();for(var t=start;t.AddMinutes(s.DurationMinutes)<=end;t=t.AddMinutes(30))if((date!=DateOnly.FromDateTime(now)||t>now)&&!busy.Any(a=>t<a.StartAt.AddMinutes(a.DurationMinutes)&&t.AddMinutes(s.DurationMinutes)>a.StartAt))slots.Add(t.ToString("HH:mm"));return Results.Ok(slots);});
app.MapPost("/api/appointments",async(CreateAppointment r,BookingDb db)=>{if(string.IsNullOrWhiteSpace(r.CustomerName))return Results.BadRequest("Customer name is required.");var s=await db.Services.FindAsync(r.ServiceId);if(s is null||!s.IsActive)return Results.BadRequest("Service is unavailable.");if(r.StartAt<DateTime.Now||r.StartAt.TimeOfDay<new TimeSpan(9,0,0)||r.StartAt.AddMinutes(s.DurationMinutes).TimeOfDay>new TimeSpan(18,0,0))return Results.BadRequest("Choose a future time between 9 AM and 6 PM.");if(await db.Appointments.AnyAsync(a=>a.Status!="Cancelled"&&a.StartAt<r.StartAt.AddMinutes(s.DurationMinutes)&&a.StartAt.AddMinutes(a.DurationMinutes)>r.StartAt))return Results.Conflict("That time was just booked.");var a=new Appointment{CustomerName=r.CustomerName.Trim(),Phone=r.Phone,ServiceId=s.Id,ServiceName=s.Name,Price=s.Price,DurationMinutes=s.DurationMinutes,StartAt=r.StartAt,Status="Confirmed"};db.Appointments.Add(a);await db.SaveChangesAsync();return Results.Created($"/api/appointments/{a.Id}",a);});
app.MapPut("/api/appointments/{id:int}",async(int id,EditAppointment r,BookingDb db)=>{var a=await db.Appointments.FindAsync(id);if(a is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(r.CustomerName))return Results.BadRequest("Customer name is required.");var s=await db.Services.FindAsync(r.ServiceId);if(s is null||!s.IsActive)return Results.BadRequest("Service is unavailable.");if(r.StartAt<DateTime.Now||r.StartAt.TimeOfDay<new TimeSpan(9,0,0)||r.StartAt.AddMinutes(s.DurationMinutes).TimeOfDay>new TimeSpan(18,0,0))return Results.BadRequest("Choose a future time between 9 AM and 6 PM.");if(await db.Appointments.AnyAsync(x=>x.Id!=id&&x.Status!="Cancelled"&&x.StartAt<r.StartAt.AddMinutes(s.DurationMinutes)&&x.StartAt.AddMinutes(x.DurationMinutes)>r.StartAt))return Results.Conflict("That time overlaps another appointment.");a.CustomerName=r.CustomerName.Trim();a.Phone=r.Phone;a.ServiceId=s.Id;a.ServiceName=s.Name;a.Price=s.Price;a.DurationMinutes=s.DurationMinutes;a.StartAt=r.StartAt;await db.SaveChangesAsync();return Results.Ok(a);});
app.MapDelete("/api/appointments/{id:int}",async(int id,BookingDb db)=>{var a=await db.Appointments.FindAsync(id);if(a is null)return Results.NotFound();db.Appointments.Remove(a);await db.SaveChangesAsync();return Results.NoContent();});
app.MapPatch("/api/appointments/{id:int}/status",async(int id,UpdateStatus r,BookingDb db)=>{var a=await db.Appointments.FindAsync(id);if(a is null)return Results.NotFound();if(!new[]{"Confirmed","Checked in","Completed","Cancelled","No show"}.Contains(r.Status))return Results.BadRequest("Invalid status.");a.Status=r.Status;await db.SaveChangesAsync();return Results.Ok(a);});app.Run();
record CreateAppointment(string CustomerName,string? Phone,int ServiceId,DateTime StartAt);record EditAppointment(string CustomerName,string? Phone,int ServiceId,DateTime StartAt);record UpdateStatus(string Status);
class BookingDb(DbContextOptions<BookingDb> o):DbContext(o){public DbSet<Appointment> Appointments=>Set<Appointment>();public DbSet<Service> Services=>Set<Service>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Appointment>().Property(x=>x.Price).HasColumnType("decimal(10,2)");b.Entity<Appointment>().HasIndex(x=>x.StartAt);b.Entity<Service>().Property(x=>x.Price).HasColumnType("decimal(10,2)");}}
class Appointment{public int Id{get;set;}public string CustomerName{get;set;}="";public string? Phone{get;set;}public int ServiceId{get;set;}public string ServiceName{get;set;}="";public decimal Price{get;set;}public int DurationMinutes{get;set;}public DateTime StartAt{get;set;}public string Status{get;set;}="Confirmed";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}
class  Service{public int Id{get;set;}public string Name{get;set;}="";public int DurationMinutes{get;set;}public decimal Price{get;set;}public bool IsActive{get;set;}=true;}
